ee:variables.ee:set-variable:
%dw 2.0
output application/json
---
{
    InventoryDate: vars."tisData"."Products"."InventoryDate",
    Products: vars."tisData"."Products" mapObject ((productList, productName) -> 
        (productName): productList map ((item) -> {
            Tank: item.Tank,
            Product: item.Product,
            GrossProduct: item.GrossProduct
        })
    )
}

%dw 2.0 output application/json var columnCount= vars.tisColumnCount var letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
fun toExcelColumn(n) = if (n <= 0) "" else do { var rem = (n - 1) mod 26 var quotient = floor((n - 1) / 26) --- toExcelColumn(quotient) ++ letters[(rem) as Number] }
--- { PresentColumnNumber: columnCount, PresentColumn: toExcelColumn(columnCount), NextColumnNumber: columnCount +1 , NextColumn: toExcelColumn(columnCount + 1) }

%dw 2.0
output application/json

var from1 = "A"
var flag= vars.flag
var nextCol = vars.columnCountAndExcelColumn.NextColumn
var presentCol = vars.columnCountAndExcelColumn.PresentColumn
var data = payload.formulas[sizeOf(payload.formulas)-2 to sizeOf(payload.formulas)-1]

---
{
  values: data map ((row) ->
  if(flag=="update")
    row map ((cell) ->
      if (cell is String and sizeOf(cell) > 0 and cell[0] == "=")
        cell replace (("(?:" ++ from1 ++ ")(?=\\d|\\\$)") as Regex) with presentCol
      else cell
    )
    else row map ((cell) ->
      if (cell is String and sizeOf(cell) > 0 and cell[0] == "=")
        cell replace (("(?:" ++ from1 ++ ")(?=\\d|\\\$)") as Regex) with nextCol
      else cell
    )
  )
}

%dw 2.0
output application/json
var tanks = vars."newTanks"
var productsdata = vars."filteredTisData"."Products"
var colCount= vars.tisColumnCount
---
{	index: vars."NewProductRowIndex",
    values: tanks map (t) -> do {
        var product = flatten(
            productsdata pluck ((items, key) ->
                (items filter ((i) -> i.Tank == t)) map ((i) -> key)
            )
        )
        ---
        [t, if (sizeOf(product) > 0) product[0] else ""] 
        ++ (0 to (colCount - 2 - 1) map ((i) -> "0.0"))
    }
}

%dw 2.0
output application/json
var template = flatten(vars."tisTemplate"."Tanks")
var data = vars."filteredTisData"."Products"
var date= vars."inventoryDate" as Date {format: "d-MMM-yyyy"}

var coldata= {
    "values":  template map (t) -> do {
    // Remove this line → var tank = t[0]
    var match = flatten(
        data pluck ((v, k) ->
            (v filter (item) -> item.Tank == t) map ((item) -> item.GrossProduct)
        )
    ) filter ((item) -> item != null)
    ---
    if (sizeOf(match) > 0) [match[0]] else ["0.0"]
}
}

---
values: [[date]] ++ coldata.values ++ [[""],[""],[vars."replacedFormulas".values[0][0]], [vars."replacedFormulas".values[1][0]]]
